from typing import List
from collections import defaultdict

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        n = len(nums)
        # max possible absolute alternating sum
        max_sum = sum(nums)  # each element at most adds |v|
        if k > max_sum or k < -max_sum:
            return -1

        cap = limit + 1  # marker for products exceeding limit

        # dp: key = (alternating_sum, parity_of_next_index) -> set of products
        # parity 0 means next element to be added goes at even index (+v)
        # parity 1 means next element goes at odd index (-v)
        # We store states as (sum, parity_next) where parity_next is parity of NEXT position.
        dp = defaultdict(set)

        for i, v in enumerate(nums):
            remaining_after = n - i - 1
            max_change = 12 * remaining_after

            additions = defaultdict(set)

            # extend existing subsequences
            for (s, p), prods in dp.items():
                if p == 0:
                    ns = s + v
                else:
                    ns = s - v
                np = 1 - p
                # prune: if ns can't reach k with remaining elements, skip
                if abs(ns - k) > max_change:
                    continue
                tgt = additions[(ns, np)]
                if v == 0:
                    tgt.add(0)
                elif v == 1:
                    tgt |= prods
                else:
                    for pr in prods:
                        npr = pr * v
                        if npr > limit:
                            npr = cap
                        tgt.add(npr)

            # start new subsequence with v at index 0 (even), next parity = 1
            if abs(v - k) <= max_change:
                pv = v if v <= limit else cap
                additions[(v, 1)].add(pv)

            # merge
            for key, prods in additions.items():
                dp[key] |= prods

        best = -1
        for p in (0, 1):
            prods = dp.get((k, p))
            if prods:
                for pr in prods:
                    if pr <= limit and pr > best:
                        best = pr
        return best

