                print(-1)
                return
        else:
            f[a] = b

    # If S uses all 26 letters and f is injective (permutation) and S != T -> impossible
    if len(f) == 26 and len(set(f.values())) == 26:
        print(-1)
        return

    ops = sum(1 for x in f if f[x] != x)

    # find cycles of length >= 2 in functional graph restricted to domain of f
    color = {x: 0 for x in f}  # 0 = white, 1 = gray (in current path), 2 = black (done)
    cycles = 0
    for start in f:
        if color[start] != 0:
            continue
        path = []
        x = start
        while x in f and color[x] == 0:
            color[x] = 1
            path.append(x)
            x = f[x]
        if x in f and color[x] == 1:
            # cycle found containing x
            if f[x] != x:  # length >= 2 (self-loops excluded)
                cycles += 1
        for y in path:
            color[y] = 2

    print(ops + cycles)

