def build(R,B):
    if R&1: return None
    if R==0:
        if B&1: return None
        p=(B-2)//2
        return [('B',i,i) for i in range(p+1)]+[('B',p+1-j,p-1-j) for j in range(p+1)]
    if B==0:
        if R==2: return [('R',0,0),('R',0,1)]
        m=R//2
        return [('R',0,j) for j in range(m)]+[('R',1,j) for j in range(m-1,-1,-1)]
    if R>=2*B:
        k=(R-2*B)//2
        cells=[('B',i,i) for i in range(B)]
        cells.append(('R',B,B))
        for j in range(1,k+1): cells.append(('R',B,B+j))
        for i in range(B-1,-1,-1): cells.append(('R',i,B+k))
        for j in range(B+k-1,0,-1): cells.append(('R',0,j))
        return cells
    # R < 2B, B >= 2, base V with 2 reds + insertions
    if B%2==0:
        p=(B-2)//2
        bl=[(i,i) for i in range(p+1)]+[(p+1-j,p-1-j) for j in range(p+1)]
        red1=(0,-2)
    else:
        p=(B-1)//2
        bl=[(i,i) for i in range(p+1)]+[(p+1-j,p-1-j) for j in range(p)]
        red1=(1,-1)
    red2=(0,-1)
    m=(R-2)//2
    cells=[]
    for t in range(B):
        r,c=bl[t]
        cells.append(('B',r,c))
        if t<m:
            if t+1<B: nr,nc=bl[t+1]
            else: nr,nc=red1
            dr=nr-r; dc=nc-c
            if dr==1 and dc==1: a,b=(r-1,c+1),(r,c+1)
            elif dr==1 and dc==-1: a,b=(r+1,c+1),(r+1,c)
            elif dr==-1 and dc==-1: a,b=(r+1,c-1),(r,c-1)
            else: a,b=(r-1,c-1),(r-1,c)
            cells.append(('R',a[0],a[1]))
            cells.append(('R',b[0],b[1]))
    cells.append(('R',red1[0],red1[1]))
    cells.append(('R',red2[0],red2[1]))
    return cells

def main():
