        pe = [NEG]*(R-1)
        for p in range(R-1):
            best = pe[p-2] if p >= 2 else NEG
            if p >= 1 and p+1 <= R-1 and v[p-1] == v[p+1]:
                best = p
            pe[p] = best
        # run1[j]: leftmost index of consecutive c==1 block ending at run j
        run1 = [0]*R
        for j in range(R):
            if c[j] == 1:
                run1[j] = run1[j-1] if (j > 0 and c[j-1] == 1) else j
            else:
                run1[j] = 10**9
        # m[q]: minimal chain start p (same parity) with v[j]==v[j+3] for j=p..q-2 step2
        m = [0]*(R-1)
        for q in range(R-1):
            if q-2 >= 1 and q+1 <= R-1 and v[q-2] == v[q+1]:
                m[q] = m[q-2]
            else:
                m[q] = q
        f = [0]*(R-1)
        for q in range(R-1):
            cur = f[q-1] if q >= 1 else 0
            if 1 <= q <= R-3 and v[q] == v[q+2] and c[q+1] == 1 and c[q] == 1:
                bound = m[q]
                if run1[q+1] > bound:
