def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0]); m = int(data[1])
    adj = [[] for _ in range(n + 1)]
    idx = 2
    for _ in range(m):
        u = int(data[idx]); v = int(data[idx + 1]); idx += 2
        adj[u].append(v); adj[v].append(u)

    color = [-1] * (n + 1)
    k = 0          # number of odd-size components
    sigma = 0      # number of singleton components
    evenC = 0      # parity sum of side-size over even components
    big_odd = False

    for s in range(1, n + 1):
        if color[s] != -1:
            continue
        color[s] = 0
        cnt0 = 1
        size = 1
        stack = [s]
        while stack:
            u = stack.pop()
            cu = color[u]
            for w in adj[u]:
                if color[w] == -1:
                    color[w] = cu ^ 1
                    if color[w] == 0:
                        cnt0 += 1
                    size += 1
                    stack.append(w)
        if size % 2 == 1:
            k += 1
            if size == 1:
                sigma += 1
            else:
                big_odd = True
        else:
            evenC ^= (cnt0 & 1)

    if n % 2 == 1:
        ans = (m % 2 == 1)
    else:
        if k == 0:
            ans = ((evenC + m) % 2 == 1)
        elif k == 2:
            if big_odd:
                ans = True
            else:
                ans = ((evenC + 1 + m) % 2 == 1)
        else:
            if sigma == k:
                ans = ((evenC + k // 2 + m) % 2 == 1)
            elif sigma >= k - 2:
                ans = True
            else:
                ans = (m % 2 == 1)

    print("Aoki" if ans else "Takahashi")

