from collections import deque

def main():
    sys.setrecursionlimit(20000)
    data = sys.stdin.read().split()
    idx = 0
    N = int(data[idx]); idx += 1
    M = int(data[idx]); idx += 1
    K = int(data[idx]); idx += 1
    edges = []
    for _ in range(M):
        u = int(data[idx]); idx += 1
        v = int(data[idx]); idx += 1
        edges.append((u, v))
    INF = 10**7

    def mincut(d):
        n = N * d + 2
        S = N * d
        T = N * d + 1
        graph = [[] for _ in range(n)]
        def add(a, b, c):
            graph[a].append([b, c, len(graph[b])])
            graph[b].append([a, 0, len(graph[a]) - 1])
        def nid(v, i):
            return (v - 1) * d + (i - 1)
        # monotonicity: p_v >= i+1 implies p_v >= i
        for v in range(1, N + 1):
            for i in range(1, d):
                add(nid(v, i + 1), nid(v, i), INF)
        # p_N = d (all N_i source side), p_1 = 0 (all 1_i sink side)
        for i in range(1, d + 1):
            add(S, nid(N, i), INF)
            add(nid(1, i), T, INF)
        for (u, v) in edges:
            # hard constraint p_v <= p_u + 1
            for i in range(1, d):
                add(nid(v, i + 1), nid(u, i), INF)
            # cost 1 if p_v = p_u + 1
            for i in range(1, d + 1):
                add(nid(v, i), nid(u, i), 1)
        # Dinic
        flow = 0
        while True:
            level = [-1] * n
            level[S] = 0
            q = deque([S])
            while q:
                x = q.popleft()
                for e in graph[x]:
                    if e[1] > 0 and level[e[0]] < 0:
                        level[e[0]] = level[x] + 1
                        q.append(e[0])
            if level[T] < 0:
                break
            it = [0] * n
            def dfs(x, f):
                if x == T:
                    return f
                while it[x] < len(graph[x]):
                    e = graph[x][it[x]]
                    if e[1] > 0 and level[e[0]] == level[x] + 1:
                        r = dfs(e[0], min(f, e[1]))
                        if r > 0:
                            e[1] -= r
                            graph[e[0]][e[2]][1] += r
                            return r
                    it[x] += 1
                return 0
            while True:
                f = dfs(S, INF * 1000)
                if f == 0:
                    break
                flow += f
                if flow > K:
                    return flow
        return flow

    ans = 0
    for d in range(min(K, N - 1), 0, -1):
        if mincut(d) <= K:
            ans = d
            break
    print(ans)

