class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        m = len(conflictingPairs)
        buckets = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            buckets[b].append((a, i))

        # For each right endpoint r, valid left endpoints l satisfy:
        # for every pair (a,b) with b <= r, we need l > a  =>  l > max_a
        # count for r = r - max1 (max1 = 0 if no constraints)
        # If we remove the pair achieving max1 (unique holder id1), new count = r - max2
        # Gain attributed to that pair = max1 - max2 at each r.

        max1 = 0
        max2 = 0
        id1 = -1  # index of pair holding max1

        base = 0
        gains = [0] * m

        for r in range(1, n + 1):
            for a, i in buckets[r]:
                if a > max1:
                    max2 = max1
                    max1 = a
                    id1 = i
                elif a > max2:
                    max2 = a
            base += r - max1
            if id1 >= 0:
                gains[id1] += max1 - max2

        return base + max(gains)

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        N = n + m - 1
        res = [''] * N

        # Place str2 at all 'T' positions, check consistency
        for i, ch in enumerate(str1):
            if ch == 'T':
                for j in range(m):
                    cur = res[i + j]
                    c = str2[j]
                    if cur:
                        if cur != c:
                            return ""
                    else:
                        res[i + j] = c

        # Mark free positions and fill them with 'a'
        free = [False] * N
        for i in range(N):
            if not res[i]:
                res[i] = 'a'
                free[i] = True

        s2 = list(str2)

        # Handle 'F' constraints left to right
        for i in range(n):
            if str1[i] == 'F' and res[i:i + m] == s2:
                # window matches str2 but must not; flip rightmost free position
                j = i + m - 1
                while j >= i and not free[j]:
                    j -= 1
                if j < i:
                    return ""
                # window matched, so res[j] == str2[j-i]; free means res[j]=='a'
                res[j] = 'b'
                free[j] = False  # lock it so it never gets reverted

        return ''.join(res)

