class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        CAP = 2 * 10**15  # cap, since k <= 1e15
        fact = [1] * (n + 2)
        for i in range(1, n + 2):
            fact[i] = min(fact[i - 1] * i, CAP)

        odds = [x for x in range(1, n + 1) if x % 2 == 1]
        evens = [x for x in range(1, n + 1) if x % 2 == 0]

        def feasible(m, start_p, o, e):
            # m remaining positions, first must have parity start_p (1=odd,0=even)
            if m == 0:
                return o == 0 and e == 0
            need_odd = (m + 1) // 2 if start_p == 1 else m // 2
            return o == need_odd and e == m - need_odd

        result = []
        prev_parity = None

        for i in range(n):
            placed = False
            if prev_parity is None:
                candidates = sorted(odds + evens)
            else:
                candidates = odds if prev_parity == 0 else evens

            for v in candidates:
                p = v % 2
                o = len(odds) - (1 if p == 1 else 0)
                e = len(evens) - (1 if p == 0 else 0)
                m = n - i - 1
                if m == 0:
                    if o == 0 and e == 0:
                        ways = 1
                    else:
                        continue
                else:
                    next_p = 1 - p
                    if not feasible(m, next_p, o, e):
                        continue
                    ways = min(fact[o] * fact[e], CAP)

                if k <= ways:
                    result.append(v)
                    if p == 1:
                        odds.remove(v)
                    else:
                        evens.remove(v)
                    prev_parity = p
                    placed = True
                    break
                else:
                    k -= ways

            if not placed:
                return []

        return result

