class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        s = side
        L = 4 * s
        pos = []
        for x, y in points:
            if y == 0:
                p = x
            elif x == s:
                p = s + y
            elif y == s:
                p = 3 * s - x
            else:  # x == 0
                p = 4 * s - y
            pos.append(p)
        pos.sort()
        n = len(pos)
        ext = pos + [p + L for p in pos]
        INF = float('inf')
        extv = ext + [INF]
        N2 = 2 * n
        steps = k - 1

        def check(d):
            # next pointer: smallest j with ext[j] >= ext[i] + d
            nxt = [N2] * (N2 + 1)
            j = 0
            for i in range(N2):
                t = ext[i] + d
                while j < N2 and ext[j] < t:
                    j += 1
                nxt[i] = j
            # nxt[N2] = N2 (sentinel)
            # binary lifting: collect tables for set bits of steps
            tables = []
            b = steps
            cur = nxt
            while b:
                if b & 1:
                    tables.append(cur)
                b >>= 1
                if b:
                    cur = [cur[v] for v in cur]
            Ld = L - d
            for i in range(n):
                c = i
                for t in tables:
                    c = t[c]
                    if c == N2:
                        break
                if extv[c] <= pos[i] + Ld:
                    return True
            return False

        lo, hi = 1, L // k  # answer <= 4*side/k <= side since k >= 4
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if check(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

