class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])
        nxt = [2, 2, 0]  # value 0 -> next 2, value 1 -> next 2, value 2 -> next 0
        # clockwise order of diagonal directions
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]

        # f[d][i][j] = length of longest segment starting at (i,j) going dir d,
        # following the alternating pattern based on grid[i][j]
        f = [[[1] * m for _ in range(n)] for _ in range(4)]

        # dir 0: (1,1) -> iterate i desc, j desc
        f0 = f[0]
        for i in range(n - 2, -1, -1):
            gi = grid[i]; gi1 = grid[i + 1]
            fi = f0[i]; fi1 = f0[i + 1]
            for j in range(m - 2, -1, -1):
                if gi1[j + 1] == nxt[gi[j]]:
                    fi[j] = fi1[j + 1] + 1

        # dir 1: (1,-1) -> iterate i desc, j asc
        f1 = f[1]
        for i in range(n - 2, -1, -1):
            gi = grid[i]; gi1 = grid[i + 1]
            fi = f1[i]; fi1 = f1[i + 1]
            for j in range(1, m):
                if gi1[j - 1] == nxt[gi[j]]:
                    fi[j] = fi1[j - 1] + 1

        # dir 2: (-1,-1) -> iterate i asc, j asc
        f2 = f[2]
        for i in range(1, n):
            gi = grid[i]; gi1 = grid[i - 1]
            fi = f2[i]; fi1 = f2[i - 1]
            for j in range(1, m):
                if gi1[j - 1] == nxt[gi[j]]:
                    fi[j] = fi1[j - 1] + 1

        # dir 3: (-1,1) -> iterate i asc, j desc
        f3 = f[3]
        for i in range(1, n):
            gi = grid[i]; gi1 = grid[i - 1]
            fi = f3[i]; fi1 = f3[i - 1]
            for j in range(m - 2, -1, -1):
                if gi1[j + 1] == nxt[gi[j]]:
                    fi[j] = fi1[j + 1] + 1

        ans = 0
        for i in range(n):
            gi = grid[i]
            for j in range(m):
                if gi[j] != 1:
                    continue
                for d in range(4):
                    dx, dy = dirs[d]
                    L = f[d][i][j]
                    if L > ans:
                        ans = L
                    d2 = (d + 1) % 4
                    ex, ey = dirs[d2]
                    fd2 = f[d2]
                    x, y = i, j
                    # walk along direction d; at each cell try turning clockwise
                    for t in range(L):
                        nx, ny = x + ex, y + ey
                        if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] == nxt[grid[x][y]]:
                            cand = t + 1 + fd2[nx][ny]
                            if cand > ans:
                                ans = cand
                        x += dx
                        y += dy
        return ans

