class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        i1 = p.index('*')
        i2 = p.index('*', i1 + 1)
        p1, p2, p3 = p[:i1], p[i1+1:i2], p[i2+1:]
        n = len(s)

        def kmp_all(text, pat):
            m = len(pat)
            if m == 0:
                return list(range(len(text) + 1))
            f = [0] * m
            k = 0
            for i in range(1, m):
                c = pat[i]
                while k and c != pat[k]:
                    k = f[k-1]
                if c == pat[k]:
                    k += 1
                f[i] = k
            res = []
            k = 0
            for i, c in enumerate(text):
                while k and c != pat[k]:
                    k = f[k-1]
                if c == pat[k]:
                    k += 1
                if k == m:
                    res.append(i - m + 1)
                    k = f[k-1]
            return res

        A = kmp_all(s, p1)  # start positions of p1
        B = kmp_all(s, p2)
        C = kmp_all(s, p3)

        if not A or not B or not C:
            return -1

        l1, l2, l3 = len(p1), len(p2), len(p3)
        ans = float('inf')

        for j in B:
            # latest start i of p1 with i + l1 <= j
            idx = bisect.bisect_right(A, j - l1) - 1
            if idx < 0:
                continue
            i = A[idx]
            # earliest start k of p3 with k >= j + l2
            idx2 = bisect.bisect_left(C, j + l2)
            if idx2 == len(C):
                continue
            k = C[idx2]
            length = k + l3 - i
            if length < ans:
                ans = length

        return ans if ans != float('inf') else -1

