class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def check(t: int) -> bool:
            # t >= 1 assumed
            rem = m
            carry = 0
            for i in range(n):
                need = -(-t // points[i]) - carry  # ceil(t/points[i]) - carry
                if need <= 0:
                    if i == n - 1:
                        return True
                    # must pass through this position to reach later ones
                    rem -= 1
                    carry = 0
                else:
                    # arrive once (1 move) + (need-1) oscillations (2 moves each)
                    rem -= 2 * need - 1
                    carry = need - 1
                if rem < 0:
                    return False
            return rem >= 0

        lo, hi = 0, min(points) * ((m + 1) // 2)
        # binary search for largest t with check(t) True
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if check(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

