import numpy as np

def main():
    data = sys.stdin.read().split()
    N, P = int(data[0]), int(data[1])
    D = N*(N-1)//2 + 1
    half = N//2
    comb = math.comb
    dp = {}
    init = np.zeros((N+1, D), dtype=np.int64)
    init[1, 0] = 1 % P
    dp[(1, 1, 0)] = init
    for used in range(1, N):
        wA = min(D, used*(used-1)//2 + 1)
        rem = N - used
        for last in range(1, used+1):
            for parity in (0, 1):
                A = dp.get((used, last, parity))
                if A is None:
                    continue
                Asub = A[:used+1, :wA]
                for s in range(1, rem+1):
                    nused = used + s
                    wR = min(D, nused*(nused-1)//2 + 1)
                    base = s*(s-1)//2
                    if base >= wR:
                        continue
                    choose = comb(rem, s) % P
                    res = np.zeros((used+1, wR), dtype=np.int64)
                    cnt = 0
                    for j in range(s+1):
                        exp = base + last*j
                        if exp >= wR:
                            break
                        c = (comb(s, j) * choose) % P
                        if (s - j) & 1:
                            c = (P - c) % P
                        if c:
                            L = min(wA, wR - exp)
                            res[:, exp:exp+L] += c * Asub[:, :L]
                            cnt += 1
                            if cnt == 8:
                                res %= P
                                cnt = 0
                    if cnt:
                        res %= P
                    nparity = 1 - parity
                    key = (nused, s, nparity)
                    T = dp.get(key)
                    if T is None:
                        T = np.zeros((N+1, D), dtype=np.int64)
                        dp[key] = T
                    if nparity == 0:
                        T[s:used+1+s, :wR] = (T[s:used+1+s, :wR] + res) % P
                    else:
                        T[:used+1, :wR] = (T[:used+1, :wR] + res) % P
    total = np.zeros(D, dtype=np.int64)
    for last in range(1, N+1):
        for parity in (0, 1):
            A = dp.get((N, last, parity))
            if A is not None:
                total = (total + A[half]) % P
    tot = [int(v) for v in total]
    # Pascal triangle mod P
    pas = [[0]*D for _ in range(D)]
    pas[0][0] = 1 % P
    for n in range(1, D):
        row = pas[n]
        prev = pas[n-1]
        row[0] = 1 % P
        for k in range(1, n+1):
            row[k] = (prev[k-1] + prev[k]) % P
    out = []
    for M in range(N-1, D):
        sacc = 0
        for k in range(M, D):
            t = tot[k]
            if t:
                sacc += t * pas[k][M]
        out.append(sacc % P)
    sys.stdout.write(' '.join(map(str, out)))

