def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0]); m = int(data[1])
    L = [0]*m; R = [0]*m
    for i in range(m):
        L[i] = int(data[2+2*i]); R[i] = int(data[3+2*i])
    ops = ['0']*m
    out = sys.stdout

    # cost 1: full interval
    for i in range(m):
        if L[i] == 1 and R[i] == n:
            ops[i] = '1'
            out.write("1\n" + ' '.join(ops) + "\n")
            return

    # cost 2 type 1: containment (sort by L asc, R desc)
    idx = sorted(range(m), key=lambda i: (L[i], -R[i]))
    if m >= 2:
        best = idx[0]
        found = None
        for t in range(1, m):
            cur = idx[t]
            if R[cur] <= R[best]:
                found = (best, cur)  # best contains cur
                break
            best = cur
        if found:
            outer, inner = found
            ops[inner] = '2'; ops[outer] = '1'
            out.write("2\n" + ' '.join(ops) + "\n")
            return

        # cost 2 type 2: disjoint pair
        minr = idx[0]
        founddis = None
        for t in range(1, m):
            cur = idx[t]
            if L[cur] > R[minr]:
                founddis = (minr, cur)
                break
            if R[cur] < R[minr]:
                minr = cur
        if founddis:
            a, b = founddis
            ops[a] = '2'; ops[b] = '2'
            out.write("2\n" + ' '.join(ops) + "\n")
            return

    # cost 2 type 3: L=1 interval and R=N interval
    i1 = -1
    for i in range(m):
        if L[i] == 1 and (i1 < 0 or R[i] > R[i1]):
            i1 = i
    j1 = -1
    for i in range(m):
        if R[i] == n and (j1 < 0 or L[i] < L[j1]):
            j1 = i
    if i1 >= 0 and j1 >= 0:
        # i1 != j1 since no [1,n] interval exists at this point
        if L[j1] <= R[i1] + 1:
            ops[i1] = '1'; ops[j1] = '1'
        else:
            # disjoint (should have been caught, but safe)
            ops[i1] = '2'; ops[j1] = '2'
        out.write("2\n" + ' '.join(ops) + "\n")
        return

    # cost 3: all pairwise intersecting, no containment, need M >= 3
    if m >= 3:
        j = 0
        for t in range(1, m):
            if L[t] < L[j]:
                j = t
        k = 0
        for t in range(1, m):
            if R[t] > R[k]:
                k = t
        if j != k:
            i = -1
            for t in range(m):
                if t != j and t != k:
                    i = t
                    break
            ops[i] = '2'; ops[j] = '1'; ops[k] = '1'
            out.write("3\n" + ' '.join(ops) + "\n")
            return
        else:
            # j == k means that interval contains all others -> containment
            # would have been caught; safety fallback
            for t in range(m):
                if t != j:
                    ops[t] = '2'; ops[j] = '1'
                    out.write("2\n" + ' '.join(ops) + "\n")
                    return

    out.write("-1\n")

