class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)
        # runs
        runs = []
        i = 0
        while i < n:
            j = i
            while j < n and s[j] == s[i]:
                j += 1
            runs.append(j - i)
            i = j

        def can(m):
            if m == 1:
                # alternating: cost to match "0101..." or "1010..."
                c = sum(1 for idx in range(n) if (idx % 2) != (s[idx] == '1'))
                # c counts mismatches with pattern starting '0' at even? let's compute carefully
                c0 = 0  # pattern 0,1,0,1...
                for idx in range(n):
                    expected = '0' if idx % 2 == 0 else '1'
                    if s[idx] != expected:
                        c0 += 1
                return min(c0, n - c0) <= numOps
            cost = sum(L // (m + 1) for L in runs)
            return cost <= numOps

        lo, hi = 1, n
        while lo < hi:
            mid = (lo + hi) // 2
            if can(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

