class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        parent = list(range(threshold + 1))

        def find(x):
            root = x
            while parent[root] != root:
                root = parent[root]
            while parent[x] != root:
                parent[x], x = root, parent[x]
            return root

        in_nums = [False] * (threshold + 1)
        extra = 0
        for v in nums:
            if v > threshold:
                extra += 1
            else:
                in_nums[v] = True

        for v in range(1, threshold + 1):
            if in_nums[v]:
                rv = find(v)
                for m in range(2 * v, threshold + 1, v):
                    rm = find(m)
                    if rm != rv:
                        parent[rm] = rv

        roots = set()
        for v in nums:
            if v <= threshold:
                roots.add(find(v))

        return len(roots) + extra
